    "source": "def prim(n: int, adj: list[list[tuple[int, float]]], start: int = 0) -> tuple[float, list[int]]:\n    \"\"\"Prim MST (dense O(V^2)) — complete Python reference. adj[u] = [(v, w), ...] (undirected).\"\"\"\n    INF = float(\"inf\")\n    key = [INF] * n\n    parent = [-1] * n\n    in_mst = [False] * n\n    key[start] = 0\n    for _ in range(n):\n        u = -1\n        best = INF\n        for i in range(n):\n            if not in_mst[i] and key[i] < best:\n                best = key[i]\n                u = i\n        if u < 0:\n            break\n        in_mst[u] = True\n        for v, w in adj[u]:\n            if not in_mst[v] and w < key[v]:\n                key[v] = w\n                parent[v] = u\n    total = 0\n    for i in range(n):\n        if parent[i] >= 0:\n            total += key[i]\n    return total, parent\n",
