    "source": "// Prim MST (dense O(V^2)) — complete C++17 reference. adj[u] = {(v, w), ...} (undirected).\n#include <limits>\n#include <utility>\n#include <vector>\n\nstd::pair<double, std::vector<int>> prim(int n, const std::vector<std::vector<std::pair<int, double>>>& adj, int start = 0) {\n    const double INF = std::numeric_limits<double>::infinity();\n    std::vector<double> key(n, INF);\n    std::vector<int> parent(n, -1);\n    std::vector<bool> inMst(n, false);\n    key[start] = 0;\n    for (int iter = 0; iter < n; iter++) {\n        int u = -1;\n        double best = INF;\n        for (int i = 0; i < n; i++) {\n            if (!inMst[i] && key[i] < best) {\n                best = key[i];\n                u = i;\n            }\n        }\n        if (u < 0) break;\n        inMst[u] = true;\n        for (auto [v, w] : adj[u]) {\n            if (!inMst[v] && w < key[v]) {\n                key[v] = w;\n                parent[v] = u;\n            }\n        }\n    }\n    double total = 0;\n    for (int i = 0; i < n; i++) if (parent[i] >= 0) total += key[i];\n    return {total, parent};\n}\n",
