    "source": "import java.util.Arrays;\nimport java.util.List;\n\n/** Prim MST (dense O(V^2)) — complete Java reference. adj.get(u) = arcs of u (undirected). */\npublic final class Prim {\n    public record Arc(int v, double w) {}\n    public record Result(double total, int[] parent) {}\n\n    public static Result prim(int n, List<List<Arc>> adj, int start) {\n        final double INF = Double.POSITIVE_INFINITY;\n        double[] key = new double[n];\n        Arrays.fill(key, INF);\n        int[] parent = new int[n];\n        Arrays.fill(parent, -1);\n        boolean[] inMst = new boolean[n];\n        key[start] = 0;\n        for (int iter = 0; iter < n; iter++) {\n            int u = -1;\n            double best = INF;\n            for (int i = 0; i < n; i++) {\n                if (!inMst[i] && key[i] < best) {\n                    best = key[i];\n                    u = i;\n                }\n            }\n            if (u < 0) break;\n            inMst[u] = true;\n            for (Arc a : adj.get(u)) {\n                if (!inMst[a.v()] && a.w() < key[a.v()]) {\n                    key[a.v()] = a.w();\n                    parent[a.v()] = u;\n                }\n            }\n        }\n        double total = 0;\n        for (int i = 0; i < n; i++) if (parent[i] >= 0) total += key[i];\n        return new Result(total, parent);\n    }\n}\n",
