    "source": "/// Prim MST (dense O(V^2)) — complete Rust reference. adj[u] = [(v, w), ...] (undirected).\npub fn prim(n: usize, adj: &[Vec<(usize, f64)>], start: usize) -> (f64, Vec<i64>) {\n    const INF: f64 = f64::INFINITY;\n    let mut key = vec![INF; n];\n    let mut parent = vec![-1i64; n];\n    let mut in_mst = vec![false; n];\n    key[start] = 0.0;\n    for _ in 0..n {\n        let mut u: Option<usize> = None;\n        let mut best = INF;\n        for i in 0..n {\n            if !in_mst[i] && key[i] < best {\n                best = key[i];\n                u = Some(i);\n            }\n        }\n        let Some(u) = u else { break };\n        in_mst[u] = true;\n        for &(v, w) in &adj[u] {\n            if !in_mst[v] && w < key[v] {\n                key[v] = w;\n                parent[v] = u as i64;\n            }\n        }\n    }\n    let mut total = 0.0;\n    for i in 0..n {\n        if parent[i] >= 0 {\n            total += key[i];\n        }\n    }\n    (total, parent)\n}\n",
