    "source": "package algorithms\n\nimport \"math\"\n\n// Arc is an edge u–V with weight W (undirected: listed under both endpoints).\ntype Arc struct {\n\tV int\n\tW float64\n}\n\n// prim — Prim MST (dense O(V^2)), complete Go reference.\nfunc prim(n int, adj [][]Arc, start int) (float64, []int) {\n\tINF := math.Inf(1)\n\tkey := make([]float64, n)\n\tparent := make([]int, n)\n\tinMst := make([]bool, n)\n\tfor i := range key {\n\t\tkey[i], parent[i] = INF, -1\n\t}\n\tkey[start] = 0\n\tfor iter := 0; iter < n; iter++ {\n\t\tu := -1\n\t\tbest := INF\n\t\tfor i := 0; i < n; i++ {\n\t\t\tif !inMst[i] && key[i] < best {\n\t\t\t\tbest = key[i]\n\t\t\t\tu = i\n\t\t\t}\n\t\t}\n\t\tif u < 0 {\n\t\t\tbreak\n\t\t}\n\t\tinMst[u] = true\n\t\tfor _, e := range adj[u] {\n\t\t\tif !inMst[e.V] && e.W < key[e.V] {\n\t\t\t\tkey[e.V] = e.W\n\t\t\t\tparent[e.V] = u\n\t\t\t}\n\t\t}\n\t}\n\ttotal := 0.0\n\tfor i := 0; i < n; i++ {\n\t\tif parent[i] >= 0 {\n\t\t\ttotal += key[i]\n\t\t}\n\t}\n\treturn total, parent\n}\n",
